const FILE_SET = new Set(ICON_FILES);
export const ICON_BASE = '/emojis/wody';
export const iconUrl = (file) => (FILE_SET.has(file) ? `${ICON_BASE}/${file}.png` : null);
const VS16 = /️/g;
/** The icon file of a standard emoji, or null. */
export const iconFileOf = (emoji) => ICON_OF[String(emoji).replace(VS16, '')] || null;
const TOKEN_SRC = '(?:\\{|\\[)wy:([a-z0-9_]+)(?:\\}|\\])';
// One emoji sequence: flags, keycaps, pictographs with optional skin tone and joiners.
export const EMOJI_SRC = '(?:[\\u{1F1E6}-\\u{1F1FF}]{2}|[#*0-9]\\uFE0F?\\u20E3|(?:[\\u00A9\\u00AE\\u203C\\u2049\\u2122\\u2139\\u2194-\\u21AA\\u231A-\\u23FF\\u24C2\\u25AA-\\u25FE\\u2600-\\u27BF\\u2934\\u2935\\u2B05-\\u2B55\\u3030\\u303D\\u3297\\u3299\\u{1F000}-\\u{1FAFF}])(?:\\uFE0F|[\\u{1F3FB}-\\u{1F3FF}])?(?:\\u200D(?:[\\u2600-\\u27BF\\u2640\\u2642\\u2695-\\u2696\\u2708\\u2764\\u{1F000}-\\u{1FAFF}])\\uFE0F?)*)';

/** Splits a text into plain pieces and icons: [{ text } | { icon: file }]. An emoji without an icon becomes an empty icon (never a standard emoji). */
const SPLIT_RE = new RegExp(`${TOKEN_SRC}|${EMOJI_SRC}`, 'gu');       // built once: it is long and texts are split on every render
const MAYBE = /wy:|[^\u0000-\u00a8\u00af-\u2000]/u;                    // plain latin text (the common case) skips the search
export function splitIcons(text) {
  const s = String(text ?? '');
  if (!MAYBE.test(s)) return s ? [{ text: s }] : [];
  const out = []; let last = 0;
  SPLIT_RE.lastIndex = 0;
  for (const m of s.matchAll(SPLIT_RE)) {
    if (m.index > last) out.push({ text: s.slice(last, m.index) });
    out.push({ icon: m[1] ? m[1] : iconFileOf(m[0]) });
    last = m.index + m[0].length;
  }
  if (last < s.length) out.push({ text: s.slice(last) });
  return out;
}
/** The same text with every standard emoji written as its {wy:name} token (for texts that go to the bot or to Discord). */
const EMOJI_RE = new RegExp(EMOJI_SRC, 'gu');
export const toTokens = (text) => String(text ?? '').replace(EMOJI_RE, (e) => { const f = iconFileOf(e); return f ? `{wy:${f}}` : e; });
